//! `shot` (#3261, epic #3260) — the **webview capture**, so an external session (or an agent) can SEE
//! the running app instead of inferring what it looks like.
//!
//! The watcher that dispatches requests here lives in [`crate::appchan`] — one channel, one watcher,
//! routed by kind (#3274). This module is only the capture itself.
//!
//! ## Why the webview and not the screen
//! `CapturePreview` (and its mac/linux siblings) render the webview's COMPOSITED output — pixel-identical
//! to what the user sees, *including* the sandboxed preview iframe (`sandbox="allow-scripts"`, opaque
//! origin, #2824), and a render rather than a screen grab. An OS window grab of an occluded/minimized/
//! locked-session window returns black on Windows; this exists to run overnight (#3260), so that failure
//! mode is disqualifying. Verified on the real app: a MINIMIZED capture is byte-identical to a visible one.
//!
//! ## Threading
//! `with_webview` hands the closure to the WEBVIEW thread, and `CapturePreview` is asynchronous — its
//! completion handler fires later on that same thread. So the closure must only START the capture and
//! hand the bytes back through a channel; the WAIT happens on the caller's thread. Blocking inside the
//! closure would stall the message pump that has to deliver the very completion being waited on.

pub(crate) use resolve_from::resolve_from;
pub(crate) use rect_of_frame::rect_of_frame;
pub(crate) use rect_from_css::rect_from_css;
pub(crate) use capture_scale::capture_scale;
pub(crate) use destination::destination;

use bsc_shot::{is_png, keep_count, prune_captures, resolve_out, shots_dir, Rect, ShotRequest, ShotResult};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Mutex;

/// On-screen rects the frontend registers for NAMED shot targets — e.g. `"preview"` → the Design Studio's
/// component-preview element. `bsc shot preview` names a target and the app crops the webview to its
/// registered rect, so the caller never needs pixel coordinates (#3308). Managed Tauri state; the frontend
/// keeps it fresh (mount / resize) and clears it on unmount.
#[derive(Default)]
pub struct ShotTargets(pub Mutex<HashMap<String, Rect>>);

/// Register (or clear, when `rect` is `None`) a named shot target's on-screen rect. A best-effort frontend
/// call — a stale/missing rect only degrades a `preview` shot to a clear error, never a crash.
pub(crate) fn set_shot_target_rect(target: String, rect: Option<Rect>, targets: tauri::State<'_, ShotTargets>) {
    let mut map = targets.0.lock().unwrap_or_else(|e| e.into_inner());
    match rect {
        Some(r) => {
            map.insert(target, r);
        }
        None => {
            map.remove(&target);
        }
    }
}

/// Routes a target to a mounted preview FRAME by component id, instead of to the frontend-registered
/// rect map (#3469). `frame:Heatmap` ⇒ "the preview showing Heatmap", wherever it happens to sit.
pub(crate) const FRAME_PREFIX: &str = "frame:";

fn resolve_target(app: &tauri::AppHandle, id: &str, target: &str) -> Result<Rect, String> {
    if let Some(component) = target.strip_prefix(FRAME_PREFIX) {
        return rect_of_frame(app, id, component);
    }
    use tauri::Manager;
    let targets = app.state::<ShotTargets>();
    let guard = targets.0.lock().unwrap_or_else(|e| e.into_inner());
    resolve_from(&guard, target)
}

/// Resolve a request's window label to a live webview, or refuse NAMING what does exist.
///
/// Every capture path used to call `get_webview_window("main")` directly, which made the app's other
/// windows — the widget tear-offs — structurally unphotographable. This is the one place that
/// translation happens now, so the crop-scale read and the capture cannot disagree about which window
/// they are talking about; a scale factor taken from `main` while the pixels came from a widget would
/// crop the wrong region and report success.
#[cfg(any(windows, target_os = "linux"))]
fn resolve_window(app: &tauri::AppHandle, label: &str) -> Result<tauri::WebviewWindow, String> {
    use tauri::Manager;
    app.get_webview_window(label).ok_or_else(|| {
        let have: Vec<String> = app.webview_windows().keys().cloned().collect();
        bsc_shot::unknown_window_error(label, &have)
    })
}

/// How long to wait for a capture's completion callback — `CapturePreview`'s on Windows, the WebKitGTK
/// snapshot's on Linux. Shorter than the CLI's timeout so the caller gets our real error rather than a
/// bare timeout.
// It was `#[cfg(windows)]` while that was the only capturing platform, with a note that the gate was a
// Phase 1 artifact which would disappear once another arrived. Linux is that platform; the gate is gone.
// It stays out of the no-capture arm's reach, which never waits on anything.
#[cfg(any(windows, target_os = "linux"))]
const CAPTURE_TIMEOUT: std::time::Duration = std::time::Duration::from_millis(5_000);

/// Take one capture and write the PNG. `id` names the default output file when the request has no `out`.
pub fn capture(app: &tauri::AppHandle, id: &str, req: &ShotRequest) -> Result<ShotResult, String> {
    let shots = shots_dir()?;
    let out = destination(req, &shots, id);

    // Resolve the crop rect BEFORE capturing, so an unregistered target fails fast (no wasted snapshot):
    // an explicit rect wins; else a named target (e.g. "preview") resolves to the frontend-registered
    // rect; else the whole webview.
    let rect = match (req.rect, req.target.as_deref()) {
        (Some(r), _) => Some(r),
        (None, Some(t)) => Some(resolve_target(app, id, t)?),
        (None, None) => None,
    };

    // Resolved once, here, so an unknown label fails before a snapshot is attempted and the error names
    // the windows that do exist rather than a bare miss.
    let window = req.window.as_deref().unwrap_or(bsc_shot::DEFAULT_WINDOW);
    let png = capture_webview_png(app, window)?;
    if !is_png(&png) {
        return Err(format!("the webview returned {} bytes that are not a PNG", png.len()));
    }
    let (bytes, w, h) = match rect {
        Some(rect) => {
            // The rect is CSS px; the capture is DEVICE px. Derive the ratio from the capture itself
            // (never from the caller) so every crop path is corrected in one place (#3467).
            let (img_w, _) = crop::png_dimensions(&png)?;
            crop::crop_png(&png, rect, capture_scale(app, window, img_w))?
        }
        None => {
            let (w, h) = crop::png_dimensions(&png)?;
            (png, w, h)
        }
    };
    if let Some(parent) = out.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("cannot create {}: {e}", parent.display()))?;
    }
    std::fs::write(&out, &bytes).map_err(|e| format!("cannot write {}: {e}", out.display()))?;

    // Hold the shots dir to a fixed WINDOW of the newest captures, the way `take` already sweeps the
    // request channel — it otherwise only ever grows (a `baseline --kit` run alone adds one PNG per
    // component, every run). Best-effort and AFTER the write, so the capture just taken is counted and
    // is always the last thing that would go: a janitor that could fail the capture it rides along with
    // would cost more than the disk it reclaims. `prune_captures` reads one directory level, so
    // `<shots>/baselines/` — the reference set `bsc shot diff` needs — is out of its reach structurally.
    if let Some(keep) = keep_count() {
        let n = prune_captures(&shots, keep);
        if n > 0 {
            log::debug!("pruned {n} capture(s) from {} (window {keep})", shots.display());
        }
    }
    // Report the dir THIS process resolved (#4163). The caller resolved `out` in its own env; when a
    // capture then cannot be read back, the two dirs side by side name the divergence directly instead
    // of leaving a bare `os error 2` to be guessed at.
    Ok(ShotResult {
        path: out.to_string_lossy().into_owned(),
        w,
        h,
        shots_dir: Some(shots.to_string_lossy().into_owned()),
    })
}

/// Snapshot the main window's webview as PNG bytes.
///
/// Windows only for now (the maintainer's platform). mac/linux return a STATED error rather than a
/// silent black PNG — the whole point of this surface is that a capture which didn't happen must not
/// read as one that did. Their siblings (`WKWebView.takeSnapshot`, `webkit_web_view_get_snapshot`) are
/// the same shape when needed.
#[cfg(windows)]
fn capture_webview_png(app: &tauri::AppHandle, label: &str) -> Result<Vec<u8>, String> {
    use webview2_com::CapturePreviewCompletedHandler;
    use webview2_com::Microsoft::Web::WebView2::Win32::COREWEBVIEW2_CAPTURE_PREVIEW_IMAGE_FORMAT_PNG;
    use windows::Win32::Foundation::HGLOBAL;
    use windows::Win32::System::Com::IStream;
    use windows::Win32::System::Com::StructuredStorage::CreateStreamOnHGlobal;

    let window = resolve_window(app, label)?;

    // The capture completes on the WEBVIEW thread; we wait here. Blocking inside `with_webview` would
    // stall the pump that delivers the completion.
    let (tx, rx) = std::sync::mpsc::channel::<Result<Vec<u8>, String>>();
    let tx_fail = tx.clone();

    window
        .with_webview(move |webview| {
            let send_fail = |r: Result<Vec<u8>, String>| {
                let _ = tx_fail.send(r);
            };
            unsafe {
                let core = match webview.controller().CoreWebView2() {
                    Ok(c) => c,
                    Err(e) => return send_fail(Err(format!("no CoreWebView2: {e}"))),
                };
                // An HGLOBAL-backed stream (auto-growing, freed with the stream): CapturePreview writes
                // the PNG into it, then the handler rewinds + drains it.
                let stream: IStream = match CreateStreamOnHGlobal(HGLOBAL::default(), true) {
                    Ok(s) => s,
                    Err(e) => return send_fail(Err(format!("cannot create the capture stream: {e}"))),
                };
                let sink = stream.clone();
                let tx_done = tx.clone();
                // The closure receives `windows::core::Result<()>` (webview2-com maps HRESULT through
                // ClosureArg), NOT a raw HRESULT — so propagate it, don't try to `.ok()` it.
                let handler = CapturePreviewCompletedHandler::create(Box::new(move |res: windows::core::Result<()>| {
                    let out = res
                        .map_err(|e| format!("CapturePreview failed: {e}"))
                        .and_then(|()| read_stream(&sink));
                    let _ = tx_done.send(out);
                    Ok(())
                }));
                if let Err(e) = core.CapturePreview(COREWEBVIEW2_CAPTURE_PREVIEW_IMAGE_FORMAT_PNG, &stream, &handler) {
                    send_fail(Err(format!("CapturePreview call failed: {e}")));
                }
            }
        })
        .map_err(|e| format!("cannot reach the webview: {e}"))?;

    let bytes = match rx.recv_timeout(CAPTURE_TIMEOUT) {
        Ok(r) => r?,
        Err(_) => {
            return Err(format!(
                "the webview did not complete a capture within {}ms",
                CAPTURE_TIMEOUT.as_millis()
            ))
        }
    };
    if bytes.is_empty() {
        // Distinct from a COM error: an empty read means the stream was never rewound or the capture
        // produced nothing. Either way it must not reach the caller as a "successful" zero-byte PNG.
        return Err("the webview returned an empty capture".into());
    }
    Ok(bytes)
}

/// Drain an `IStream` the capture wrote into. Rewinds first — `CapturePreview` leaves the cursor at the
/// end, so reading without a seek yields zero bytes (which would look exactly like a black/empty capture).
#[cfg(windows)]
fn read_stream(stream: &windows::Win32::System::Com::IStream) -> Result<Vec<u8>, String> {
    use windows::Win32::System::Com::STREAM_SEEK_SET;
    unsafe {
        stream.Seek(0, STREAM_SEEK_SET, None).map_err(|e| format!("cannot rewind the capture stream: {e}"))?;
        let mut out: Vec<u8> = vec![];
        let mut buf = [0u8; 64 * 1024];
        loop {
            let mut read: u32 = 0;
            stream
                .Read(buf.as_mut_ptr() as *mut _, buf.len() as u32, Some(&mut read as *mut u32))
                .ok()
                .map_err(|e| format!("cannot read the capture stream: {e}"))?;
            if read == 0 {
                break;
            }
            out.extend_from_slice(&buf[..read as usize]);
        }
        Ok(out)
    }
}

/// Snapshot the webview on Linux, where the app runs on WebKitGTK.
///
/// `webkit_web_view_get_snapshot` is the sibling the Windows arm's comment names: a RENDER of the
/// webview's own content, not an OS window grab — so the sandboxed preview iframe is included, and an
/// occluded or unfocused window still produces real pixels rather than black.
///
/// # Threading — the same contract as the Windows arm, for a different reason
///
/// `with_webview` runs the closure on the GTK main thread, which is what `snapshot()` requires: it
/// asserts the calling thread owns the `MainContext` and panics otherwise. The completion callback then
/// fires later, on that same main loop — so the closure must only START the snapshot and hand the bytes
/// back through a channel. Waiting inside it would block the very loop that has to deliver the callback.
/// The wait therefore happens on the CALLER's thread, which is an appchan watcher thread, never the main
/// one.
#[cfg(target_os = "linux")]
fn capture_webview_png(app: &tauri::AppHandle, label: &str) -> Result<Vec<u8>, String> {
    use webkit2gtk::gio::Cancellable;
    use webkit2gtk::{SnapshotOptions, SnapshotRegion, WebViewExt};

    let window = resolve_window(app, label)?;

    // The snapshot completes on the WEBVIEW thread; we wait here. See the threading note above.
    let (tx, rx) = std::sync::mpsc::channel::<Result<Vec<u8>, String>>();

    window
        .with_webview(move |webview| {
            // `Visible` and not `FullDocument`: this must match what the Windows `CapturePreview`
            // produces, and what the frontend's registered crop rects are expressed in — the VIEWPORT.
            // `FullDocument` would render the whole scrollable page, silently making every named-target
            // crop land on the wrong pixels.
            //
            // `NONE` and not `TRANSPARENT_BACKGROUND`, for the same reason: the composited output the
            // user is actually looking at is opaque.
            webview.inner().snapshot(
                SnapshotRegion::Visible,
                SnapshotOptions::NONE,
                None::<&Cancellable>,
                move |res| {
                    let out = res
                        .map_err(|e| format!("webkit_web_view_get_snapshot failed: {e}"))
                        .and_then(|surface| {
                            let mut png: Vec<u8> = Vec::new();
                            surface
                                .write_to_png(&mut png)
                                .map_err(|e| format!("cannot encode the snapshot as PNG: {e}"))?;
                            Ok(png)
                        });
                    let _ = tx.send(out);
                },
            );
        })
        .map_err(|e| format!("cannot reach the webview: {e}"))?;

    let bytes = match rx.recv_timeout(CAPTURE_TIMEOUT) {
        Ok(r) => r?,
        Err(_) => {
            return Err(format!(
                "the webview did not complete a capture within {}ms",
                CAPTURE_TIMEOUT.as_millis()
            ))
        }
    };
    if bytes.is_empty() {
        // Distinct from a GError: an empty buffer means the encoder wrote nothing. It must not reach the
        // caller as a "successful" zero-byte PNG — `is_png` would reject it, but this names the cause.
        return Err("the webview returned an empty capture".into());
    }
    Ok(bytes)
}

/// The no-capture error, as a pure function so it is testable on every platform — including the ones
/// where the arm below does not compile.
///
/// It NAMES the platform. The previous text was the constant `"bsc shot is Windows-only for now"`, which
/// stayed literally true only while Windows was the only capturing platform and would have gone quietly
/// wrong the moment a second one landed — as it now has.
///
/// Gated to exactly its users — the no-capture arm, plus every platform's test run — rather than carrying
/// an `allow(dead_code)`, which would also mask a genuinely unused function later.
#[cfg(any(test, not(any(windows, target_os = "linux"))))]
fn unsupported_platform_error(os: &str) -> String {
    format!("bsc shot has no capture for this platform yet ({os}) — no capture was taken")
}

#[cfg(not(any(windows, target_os = "linux")))]
fn capture_webview_png(_app: &tauri::AppHandle, _label: &str) -> Result<Vec<u8>, String> {
    // Stated, not silent. A black PNG that reads as success is worse than no capture: the loop would
    // reason confidently about nothing. macOS's `WKWebView.takeSnapshot` is the equivalent when needed.
    Err(unsupported_platform_error(std::env::consts::OS))
}

// Clamping lives in `crop::crop_png` (where the image's real dimensions are known) and is tested there.
// Nothing here duplicates it: a second clamp would be a second source of truth for the same rule.

#[cfg(test)]
mod window_source_tests {
    //! A SOURCE-ASSERTING guard, because nothing at run time can observe the absence of a hard-coded
    //! window. The bug this replaces was silent in the worst way: the app ACCEPTED `--window` (the
    //! field deserialized fine), ignored it, captured `main`, and reported success — so a session
    //! could record a pixel verdict about a window it never photographed. Verified live on the
    //! pre-fix binary, which answered a `--window bsc-widget-spectrum` request with a 1920x1048
    //! capture of the main surface.

    /// This module's own source, up to the first test module and with comments stripped.
    ///
    /// BOTH TRIMS ARE LOAD-BEARING and both were found by the scanner reporting itself. Without the
    /// test cut, this file's own assertion strings contain `fn capture_webview_png` and inflate the
    /// arm count to five; without the comment strip, the doc paragraph explaining why the hard-coded
    /// lookup was removed is itself flagged as a hard-coded lookup. A scanner that cannot tell its
    /// subject from its own text is not evidence about the subject.
    ///
    /// RESOLVED through [`crate::testutil::module_source`], not read from a hard-coded path.
    ///
    /// This one is the reason a grep for `include_str!` is not the measurement. It read
    /// `CARGO_MANIFEST_DIR/src/shot/mod.rs` off disk, so `migrate-crate`'s refusal — which is lexical
    /// over `include_str!` — could not see it at all: clearing the four `include_str!` self-reads
    /// would have let `--apply` proceed and left these three guards panicking on a file that no longer
    /// existed. It was found by running the lib suite under `strace -e trace=openat,write
    /// --test-threads=1` and correlating each `openat` under this crate's own `src/` with the harness
    /// `write` announcing the running test.
    ///
    /// The resolver keeps the property this comment already claimed — a module that is in NEITHER home
    /// is a panic naming both, never a silent empty scan.
    fn source() -> String {
        let text = crate::testutil::module_source("shot/mod.rs");
        let code = match text.find("#[cfg(test)]") {
            Some(i) => &text[..i],
            None => panic!("no test module found — the trim is silently scanning the whole file"),
        };
        code.lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\n")
    }

    #[test]
    fn no_capture_path_resolves_a_hard_coded_window() {
        let src = source();
        // A scanner that silently stops matching reports zero offenders, which reads as a pass — so
        // assert the population it is scanning is the one expected first.
        assert!(
            src.contains("fn capture_webview_png"),
            "the scanner is looking at the wrong file — no capture function found"
        );
        let offenders: Vec<(usize, &str)> = src
            .lines()
            .enumerate()
            .filter(|(_, l)| l.contains("get_webview_window(\"main\")"))
            .map(|(i, l)| (i + 1, l.trim()))
            .collect();
        assert!(
            offenders.is_empty(),
            "a window is hard-coded, so `--window` would be accepted and ignored:\n{}",
            offenders
                .iter()
                .map(|(n, l)| format!("  line {n}: {l}"))
                .collect::<Vec<_>>()
                .join("\n")
        );
    }

    #[test]
    fn the_default_window_is_named_once_and_never_written_as_a_literal() {
        // THE BUG SHAPE, and the reason the two tests below are not enough: the
        // hard-coded lookup can be removed while `capture` still pins the label
        // to "main" one line up — the request's `window` deserializes fine, is
        // ignored, and a widget capture reports success about the main surface.
        // A bite proved the earlier guards passed against exactly that edit.
        //
        // So: no `"main"` literal anywhere in this module's real code. The
        // default has ONE home, `bsc_shot::DEFAULT_WINDOW`, and a call site that
        // wants it says so by name.
        let src = source();
        let offenders: Vec<(usize, &str)> = src
            .lines()
            .enumerate()
            .filter(|(_, l)| l.contains('"') && l.contains("main"))
            .filter(|(_, l)| l.split('"').skip(1).step_by(2).any(|lit| lit == "main"))
            .map(|(i, l)| (i + 1, l.trim()))
            .collect();
        assert!(
            offenders.is_empty(),
            "the default window is written as a literal instead of DEFAULT_WINDOW:\n{}",
            offenders.iter().map(|(n, l)| format!("  line {n}: {l}")).collect::<Vec<_>>().join("\n")
        );
        // And the request's field is what decides, rather than being read and dropped.
        assert!(
            src.contains("req.window.as_deref().unwrap_or(bsc_shot::DEFAULT_WINDOW)"),
            "`capture` no longer resolves the window from the REQUEST"
        );
    }

    #[test]
    fn every_capture_arm_takes_the_label_so_none_can_quietly_keep_its_own_default() {
        let src = source();
        let arms = src.matches("fn capture_webview_png").count();
        // Three: windows, linux, and the no-capture arm. If one is added or removed this count is
        // what says so, rather than the new arm silently going unchecked.
        assert_eq!(arms, 3, "the number of capture arms changed — recheck each takes a label");
        assert_eq!(
            src.matches("fn capture_webview_png(app: &tauri::AppHandle, label: &str)").count()
                + src.matches("fn capture_webview_png(_app: &tauri::AppHandle, _label: &str)").count(),
            arms,
            "a capture arm does not take a window label"
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// THE REGRESSION GUARD for the ten PNGs that reached the repo (merge 6b52a96d). The app used to do
    /// `req.out.as_ref().map(PathBuf::from)`, handing a relative path to `fs::write`, which anchors at
    /// this process's cwd — `src-tauri/` under `tauri dev`.
    ///
    /// The property is ABSOLUTENESS, not a specific string: given an absolute shots dir, no request may
    /// produce a relative destination, because a relative one is the only kind that can land somewhere
    /// nobody chose. Reinstate `PathBuf::from` and the two relative cases here go red.
    #[test]
    fn no_request_can_steer_a_capture_outside_the_shots_dir() {
        let shots = std::path::Path::new(if cfg!(windows) { "C:\\ws\\shots" } else { "/ws/shots" });
        let req = |out: Option<&str>| ShotRequest { out: out.map(str::to_string), ..Default::default() };

        // The two shapes that actually leaked: a bare relative file, and a relative SUBPATH.
        assert_eq!(destination(&req(Some("flat.png")), shots, "abc"), shots.join("flat.png"));
        assert_eq!(destination(&req(Some("shots/kv-retest.png")), shots, "abc"), shots.join("shots/kv-retest.png"));

        // No `out` at all ⇒ the dir's own default.
        assert_eq!(destination(&req(None), shots, "abc"), shots.join("abc.png"));

        for out in [None, Some("flat.png"), Some("shots/kv-retest.png")] {
            let got = destination(&req(out), shots, "abc");
            assert!(got.is_absolute(), "{out:?} produced a relative destination: {}", got.display());
            assert!(got.starts_with(shots), "{out:?} escaped the shots dir: {}", got.display());
        }

        // An ABSOLUTE --out stays honored — the designer's known-good workaround must keep working.
        let abs = if cfg!(windows) { "C:\\elsewhere\\x.png" } else { "/elsewhere/x.png" };
        assert_eq!(destination(&req(Some(abs)), shots, "abc"), PathBuf::from(abs));
    }

    /// The no-capture error names the platform instead of asserting a stale one.
    #[test]
    fn the_no_capture_error_names_the_platform_rather_than_hardcoding_windows() {
        let msg = unsupported_platform_error("macos");
        assert!(msg.contains("macos"), "names the platform it actually ran on: {msg}");
        assert!(msg.contains("no capture was taken"), "and says nothing was captured: {msg}");
        assert!(!msg.contains("Windows-only"), "the old text was true only while Windows was the only arm");
    }

    #[test]
    fn a_named_target_registers_resolves_and_clears() {
        // The command + resolver are thin wrappers over this map — prove the register→resolve→clear
        // contract (and that an unregistered target is a STATED error) without a Tauri app.
        let targets = ShotTargets::default();
        let rect = Rect { x: 10, y: 20, w: 300, h: 200 };

        // Unregistered ⇒ a clear error, not a whole-screen fallback.
        assert!(resolve_from(&targets.0.lock().unwrap(), "preview").is_err());

        // Register (what set_shot_target_rect(Some) does) ⇒ resolves to the rect.
        targets.0.lock().unwrap().insert("preview".into(), rect);
        assert_eq!(resolve_from(&targets.0.lock().unwrap(), "preview").unwrap(), rect);

        // Clear (set_shot_target_rect(None)) ⇒ back to the error.
        targets.0.lock().unwrap().remove("preview");
        assert!(resolve_from(&targets.0.lock().unwrap(), "preview").is_err());
    }

    // ── `frame:<component>` targeting (#3469) ─────────────────────────────────────────────────────

    #[test]
    fn a_frame_target_is_routed_away_from_the_registered_rect_map() {
        // The prefix is the whole routing rule: `frame:X` must NEVER be looked up in the named-rect
        // map (it would miss and report "navigate first" for a component that IS mounted), and a plain
        // target must never be mistaken for a frame request.
        assert_eq!("frame:Heatmap".strip_prefix(FRAME_PREFIX), Some("Heatmap"));
        assert_eq!("preview".strip_prefix(FRAME_PREFIX), None);
        // A component whose NAME contains the prefix word is still addressed by its own id.
        assert_eq!("frame:frame".strip_prefix(FRAME_PREFIX), Some("frame"));
    }

    #[test]
    fn a_css_rect_becomes_an_integer_crop_without_losing_a_partial_pixel() {
        // getBoundingClientRect() is fractional; the crop grid is integral. Floor the origin and ceil
        // the size — the same rounding the frontend applies registering `preview` — so a box that
        // partially covers a pixel keeps it.
        let r = rect_from_css([10.4, 20.6, 300.2, 199.1], "Heatmap").unwrap();
        assert_eq!(r, Rect { x: 10, y: 20, w: 301, h: 200 });
        // Exact integers pass through untouched.
        assert_eq!(rect_from_css([0.0, 0.0, 8.0, 6.0], "X").unwrap(), Rect { x: 0, y: 0, w: 8, h: 6 });
    }

    #[test]
    fn a_negative_origin_clamps_instead_of_wrapping_through_u32() {
        // A frame scrolled above/left of the viewport reports negatives. `-4.0 as u32` is 0 on this
        // path only because we clamp FIRST — without it the cast saturates/wraps and the crop lands
        // somewhere absurd, which the downstream clamp would then quietly absorb.
        let r = rect_from_css([-4.0, -12.5, 50.0, 40.0], "Offscreen").unwrap();
        assert_eq!(r, Rect { x: 0, y: 0, w: 50, h: 40 });
    }

    #[test]
    fn a_zero_size_frame_is_a_stated_error_not_a_zero_pixel_crop() {
        // Mounted but not laid out yet. Saying so beats handing back an empty PNG that reads as a
        // successful capture of nothing.
        for bad in [[0.0, 0.0, 0.0, 10.0], [0.0, 0.0, 10.0, 0.0], [0.0, 0.0, -5.0, 10.0]] {
            let err = rect_from_css(bad, "Unlaid").unwrap_err();
            assert!(err.contains("zero-size"), "{err}");
            assert!(err.contains("Unlaid"), "names the component: {err}");
        }
        // NaN must error too — every comparison against NaN is false, so a bare `<=` check would
        // have waved it through and produced a garbage crop.
        assert!(rect_from_css([0.0, 0.0, f64::NAN, 10.0], "Unlaid").is_err());
        assert!(rect_from_css([0.0, 0.0, 10.0, f64::INFINITY], "Unlaid").is_err());
    }
}

tests.src:
//! `shot` (#3261, epic #3260) — the **webview capture**, so an external session (or an agent) can SEE
//! the running app instead of inferring what it looks like.
//!
//! The watcher that dispatches requests here lives in [`crate::appchan`] — one channel, one watcher,
//! routed by kind (#3274). This module is only the capture itself.
//!
//! ## Why the webview and not the screen
//! `CapturePreview` (and its mac/linux siblings) render the webview's COMPOSITED output — pixel-identical
//! to what the user sees, *including* the sandboxed preview iframe (`sandbox="allow-scripts"`, opaque
//! origin, #2824), and a render rather than a screen grab. An OS window grab of an occluded/minimized/
//! locked-session window returns black on Windows; this exists to run overnight (#3260), so that failure
//! mode is disqualifying. Verified on the real app: a MINIMIZED capture is byte-identical to a visible one.
//!
//! ## Threading
//! `with_webview` hands the closure to the WEBVIEW thread, and `CapturePreview` is asynchronous — its
//! completion handler fires later on that same thread. So the closure must only START the capture and
//! hand the bytes back through a channel; the WAIT happens on the caller's thread. Blocking inside the
//! closure would stall the message pump that has to deliver the very completion being waited on.

use bsc_shot::{is_png, keep_count, prune_captures, resolve_out, shots_dir, Rect, ShotRequest, ShotResult};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::Mutex;


/// On-screen rects the frontend registers for NAMED shot targets — e.g. `"preview"` → the Design Studio's
/// component-preview element. `bsc shot preview` names a target and the app crops the webview to its
/// registered rect, so the caller never needs pixel coordinates (#3308). Managed Tauri state; the frontend
/// keeps it fresh (mount / resize) and clears it on unmount.
#[derive(Default)]
pub struct ShotTargets(pub Mutex<HashMap<String, Rect>>);

/// Register (or clear, when `rect` is `None`) a named shot target's on-screen rect. A best-effort frontend
/// call — a stale/missing rect only degrades a `preview` shot to a clear error, never a crash.
#[tauri::command]
pub(crate) fn set_shot_target_rect(target: String, rect: Option<Rect>, targets: tauri::State<'_, ShotTargets>) {
    let mut map = targets.0.lock().unwrap_or_else(|e| e.into_inner());
    match rect {
        Some(r) => {
            map.insert(target, r);
        }
        None => {
            map.remove(&target);
        }
    }
}

/// The rect the frontend registered for `target`, or a STATED error naming what to do — never a silent
/// fall-through to a whole-screen capture. Pure over the map so it's testable without a Tauri app.
fn resolve_from(map: &HashMap<String, Rect>, target: &str) -> Result<Rect, String> {
    map.get(target).copied().ok_or_else(|| {
        format!(
            "no '{target}' shot target is registered — the Design Studio isn't showing a component. \
             Run `bsc navigate component <kit> <component>` first, then retry."
        )
    })
}

/// Routes a target to a mounted preview FRAME by component id, instead of to the frontend-registered
/// rect map (#3469). `frame:Heatmap` ⇒ "the preview showing Heatmap", wherever it happens to sit.
pub(crate) const FRAME_PREFIX: &str = "frame:";

fn resolve_target(app: &tauri::AppHandle, id: &str, target: &str) -> Result<Rect, String> {
    if let Some(component) = target.strip_prefix(FRAME_PREFIX) {
        return rect_of_frame(app, id, component);
    }
    use tauri::Manager;
    let targets = app.state::<ShotTargets>();
    let guard = targets.0.lock().unwrap_or_else(|e| e.into_inner());
    resolve_from(&guard, target)
}

/// The on-screen rect of the mounted preview frame rendering `component` (#3469).
///
/// Reuses the `bsc debug frames` round-trip VERBATIM rather than adding a second geometry channel:
/// `FrameInfo.element.rect` is already a `getBoundingClientRect()` in CSS px — the exact units [`Rect`]
/// documents — so "photograph component X" is a CROP, not a second capture path.
///
/// Resolving app-side is also what keeps this reachable from a RESTRICTED session: the caller runs one
/// allow-listed `bsc shot frame <id>` and never needs `bsc debug` in its own command surface.
fn rect_of_frame(app: &tauri::AppHandle, id: &str, component: &str) -> Result<Rect, String> {
    let res = crate::debug::inspect(app, id, &bsc_debug::DebugRequest::Frames)?;
    let bsc_debug::DebugResult::Frames { frames } = res else {
        return Err("the frames inspection answered with the wrong result kind".into());
    };
    let found = frames.iter().find(|f| f.component == component).ok_or_else(|| {
        // Name what IS mounted — "not found" with the alternatives beats "not found" alone, and a
        // silent whole-page shot would be worse than either.
        let mounted: Vec<&str> = frames.iter().map(|f| f.component.as_str()).collect();
        if mounted.is_empty() {
            format!(
                "no component preview is mounted, so '{component}' cannot be photographed — run \
                 `bsc navigate component <kit> {component}` first, then retry"
            )
        } else {
            format!("no preview for '{component}' is mounted; currently showing: {}", mounted.join(", "))
        }
    })?;
    rect_from_css(found.element.rect, component)
}

/// A `getBoundingClientRect()` (CSS px, possibly fractional or negative) as the integer crop [`Rect`].
///
/// Floors the origin and ceils the size so a fractional box never loses a pixel it partially covers —
/// the same rounding the frontend applies when registering the `preview` rect. A negative origin (a
/// frame scrolled above/left of the viewport) clamps to 0 rather than wrapping through `as u32`.
fn rect_from_css([x, y, w, h]: [f64; 4], component: &str) -> Result<Rect, String> {
    // `is_finite` FIRST so a NaN dimension errors rather than slipping through a `<=` comparison
    // (every comparison against NaN is false, so a bare `w <= 0.0` would treat NaN as a valid size).
    if !w.is_finite() || !h.is_finite() || w <= 0.0 || h <= 0.0 {
        return Err(format!(
            "'{component}' reports a zero-size rect ({w}x{h}) — it is mounted but not laid out yet"
        ));
    }
    Ok(Rect {
        x: x.max(0.0).floor() as u32,
        y: y.max(0.0).floor() as u32,
        w: w.ceil() as u32,
        h: h.ceil() as u32,
    })
}

/// Resolve a request's window label to a live webview, or refuse NAMING what does exist.
///
/// Every capture path used to call `get_webview_window("main")` directly, which made the app's other
/// windows — the widget tear-offs — structurally unphotographable. This is the one place that
/// translation happens now, so the crop-scale read and the capture cannot disagree about which window
/// they are talking about; a scale factor taken from `main` while the pixels came from a widget would
/// crop the wrong region and report success.
#[cfg(any(windows, target_os = "linux"))]
fn resolve_window(app: &tauri::AppHandle, label: &str) -> Result<tauri::WebviewWindow, String> {
    use tauri::Manager;
    app.get_webview_window(label).ok_or_else(|| {
        let have: Vec<String> = app.webview_windows().keys().cloned().collect();
        bsc_shot::unknown_window_error(label, &have)
    })
}

/// How long to wait for a capture's completion callback — `CapturePreview`'s on Windows, the WebKitGTK
/// snapshot's on Linux. Shorter than the CLI's timeout so the caller gets our real error rather than a
/// bare timeout.
// It was `#[cfg(windows)]` while that was the only capturing platform, with a note that the gate was a
// Phase 1 artifact which would disappear once another arrived. Linux is that platform; the gate is gone.
// It stays out of the no-capture arm's reach, which never waits on anything.
#[cfg(any(windows, target_os = "linux"))]
const CAPTURE_TIMEOUT: std::time::Duration = std::time::Duration::from_millis(5_000);

/// The capture's device-pixels-per-CSS-pixel ratio (#3467).
///
/// Every crop rect arrives in CSS pixels (`getBoundingClientRect()`), while `CapturePreview` emits
/// device pixels — so on a HiDPI display the two disagree by this factor. It is derived from the
/// capture and the live window rather than trusted from a caller: `img_w / css_viewport_w`, where the
/// CSS width is the window's physical inner width over the OS scale factor. That self-corrects if the
/// captured surface is not exactly the window, and reduces to the plain scale factor when it is.
///
/// Falls back to 1.0 on anything implausible (no window, a failed query, a ratio outside a sane
/// range). A wrong-but-sane crop beats failing a capture mid-loop, and 1.0 is exactly today's
/// behaviour — so the fallback can never be worse than the bug this fixes.
fn capture_scale(app: &tauri::AppHandle, label: &str, img_w: u32) -> f64 {
    use tauri::Manager;
    // The window the pixels CAME from, not `main`: a scale read off a different window would crop the
    // wrong region of a correct capture and report success about it.
    let Some(win) = app.get_webview_window(label) else { return 1.0 };
    let size = match win.inner_size() {
        Ok(s) => s,
        Err(_) => return 1.0,
    };
    let sf = match win.scale_factor() {
        Ok(s) => s,
        Err(_) => return 1.0,
    };
    if size.width == 0 || !sf.is_finite() || sf <= 0.0 {
        return 1.0;
    }
    let css_w = size.width as f64 / sf;
    if css_w <= 0.0 {
        return 1.0;
    }
    let scale = img_w as f64 / css_w;
    // A real display is 1.0–4.0; anything outside a generous band means a query we misread.
    if !scale.is_finite() || !(0.25..=8.0).contains(&scale) {
        return 1.0;
    }
    scale
}

/// Where this capture's PNG goes — named and separated from [`capture`] purely so it is TESTABLE, since
/// `capture` needs a live `AppHandle` and this is the line that got it wrong.
///
/// It must go through the shared [`resolve_out`] and never `PathBuf::from` alone: a bare relative `out`
/// reaches `fs::write` below and anchors at THIS process's cwd — `src-tauri/` under `tauri dev`. That is
/// how ten captures came to be committed to the repo (merge 6b52a96d); each reported success, at a path
/// nobody had asked for. The CLI resolves the caller's half the same way (#3662).
fn destination(req: &ShotRequest, shots: &std::path::Path, id: &str) -> PathBuf {
    resolve_out(req.out.as_deref(), shots, id)
}

/// Take one capture and write the PNG. `id` names the default output file when the request has no `out`.
pub fn capture(app: &tauri::AppHandle, id: &str, req: &ShotRequest) -> Result<ShotResult, String> {
    let shots = shots_dir()?;
    let out = destination(req, &shots, id);

    // Resolve the crop rect BEFORE capturing, so an unregistered target fails fast (no wasted snapshot):
    // an explicit rect wins; else a named target (e.g. "preview") resolves to the frontend-registered
    // rect; else the whole webview.
    let rect = match (req.rect, req.target.as_deref()) {
        (Some(r), _) => Some(r),
        (None, Some(t)) => Some(resolve_target(app, id, t)?),
        (None, None) => None,
    };

    // Resolved once, here, so an unknown label fails before a snapshot is attempted and the error names
    // the windows that do exist rather than a bare miss.
    let window = req.window.as_deref().unwrap_or(bsc_shot::DEFAULT_WINDOW);
    let png = capture_webview_png(app, window)?;
    if !is_png(&png) {
        return Err(format!("the webview returned {} bytes that are not a PNG", png.len()));
    }
    let (bytes, w, h) = match rect {
        Some(rect) => {
            // The rect is CSS px; the capture is DEVICE px. Derive the ratio from the capture itself
            // (never from the caller) so every crop path is corrected in one place (#3467).
            let (img_w, _) = crop::png_dimensions(&png)?;
            crop::crop_png(&png, rect, capture_scale(app, window, img_w))?
        }
        None => {
            let (w, h) = crop::png_dimensions(&png)?;
            (png, w, h)
        }
    };
    if let Some(parent) = out.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("cannot create {}: {e}", parent.display()))?;
    }
    std::fs::write(&out, &bytes).map_err(|e| format!("cannot write {}: {e}", out.display()))?;

    // Hold the shots dir to a fixed WINDOW of the newest captures, the way `take` already sweeps the
    // request channel — it otherwise only ever grows (a `baseline --kit` run alone adds one PNG per
    // component, every run). Best-effort and AFTER the write, so the capture just taken is counted and
    // is always the last thing that would go: a janitor that could fail the capture it rides along with
    // would cost more than the disk it reclaims. `prune_captures` reads one directory level, so
    // `<shots>/baselines/` — the reference set `bsc shot diff` needs — is out of its reach structurally.
    if let Some(keep) = keep_count() {
        let n = prune_captures(&shots, keep);
        if n > 0 {
            log::debug!("pruned {n} capture(s) from {} (window {keep})", shots.display());
        }
    }
    // Report the dir THIS process resolved (#4163). The caller resolved `out` in its own env; when a
    // capture then cannot be read back, the two dirs side by side name the divergence directly instead
    // of leaving a bare `os error 2` to be guessed at.
    Ok(ShotResult {
        path: out.to_string_lossy().into_owned(),
        w,
        h,
        shots_dir: Some(shots.to_string_lossy().into_owned()),
    })
}

/// Snapshot the main window's webview as PNG bytes.
///
/// Windows only for now (the maintainer's platform). mac/linux return a STATED error rather than a
/// silent black PNG — the whole point of this surface is that a capture which didn't happen must not
/// read as one that did. Their siblings (`WKWebView.takeSnapshot`, `webkit_web_view_get_snapshot`) are
/// the same shape when needed.
#[cfg(windows)]
fn capture_webview_png(app: &tauri::AppHandle, label: &str) -> Result<Vec<u8>, String> {
    use webview2_com::CapturePreviewCompletedHandler;
    use webview2_com::Microsoft::Web::WebView2::Win32::COREWEBVIEW2_CAPTURE_PREVIEW_IMAGE_FORMAT_PNG;
    use windows::Win32::Foundation::HGLOBAL;
    use windows::Win32::System::Com::IStream;
    use windows::Win32::System::Com::StructuredStorage::CreateStreamOnHGlobal;

    let window = resolve_window(app, label)?;

    // The capture completes on the WEBVIEW thread; we wait here. Blocking inside `with_webview` would
    // stall the pump that delivers the completion.
    let (tx, rx) = std::sync::mpsc::channel::<Result<Vec<u8>, String>>();
    let tx_fail = tx.clone();

    window
        .with_webview(move |webview| {
            let send_fail = |r: Result<Vec<u8>, String>| {
                let _ = tx_fail.send(r);
            };
            unsafe {
                let core = match webview.controller().CoreWebView2() {
                    Ok(c) => c,
                    Err(e) => return send_fail(Err(format!("no CoreWebView2: {e}"))),
                };
                // An HGLOBAL-backed stream (auto-growing, freed with the stream): CapturePreview writes
                // the PNG into it, then the handler rewinds + drains it.
                let stream: IStream = match CreateStreamOnHGlobal(HGLOBAL::default(), true) {
                    Ok(s) => s,
                    Err(e) => return send_fail(Err(format!("cannot create the capture stream: {e}"))),
                };
                let sink = stream.clone();
                let tx_done = tx.clone();
                // The closure receives `windows::core::Result<()>` (webview2-com maps HRESULT through
                // ClosureArg), NOT a raw HRESULT — so propagate it, don't try to `.ok()` it.
                let handler = CapturePreviewCompletedHandler::create(Box::new(move |res: windows::core::Result<()>| {
                    let out = res
                        .map_err(|e| format!("CapturePreview failed: {e}"))
                        .and_then(|()| read_stream(&sink));
                    let _ = tx_done.send(out);
                    Ok(())
                }));
                if let Err(e) = core.CapturePreview(COREWEBVIEW2_CAPTURE_PREVIEW_IMAGE_FORMAT_PNG, &stream, &handler) {
                    send_fail(Err(format!("CapturePreview call failed: {e}")));
                }
            }
        })
        .map_err(|e| format!("cannot reach the webview: {e}"))?;

    let bytes = match rx.recv_timeout(CAPTURE_TIMEOUT) {
        Ok(r) => r?,
        Err(_) => {
            return Err(format!(
                "the webview did not complete a capture within {}ms",
                CAPTURE_TIMEOUT.as_millis()
            ))
        }
    };
    if bytes.is_empty() {
        // Distinct from a COM error: an empty read means the stream was never rewound or the capture
        // produced nothing. Either way it must not reach the caller as a "successful" zero-byte PNG.
        return Err("the webview returned an empty capture".into());
    }
    Ok(bytes)
}

/// Drain an `IStream` the capture wrote into. Rewinds first — `CapturePreview` leaves the cursor at the
/// end, so reading without a seek yields zero bytes (which would look exactly like a black/empty capture).
#[cfg(windows)]
fn read_stream(stream: &windows::Win32::System::Com::IStream) -> Result<Vec<u8>, String> {
    use windows::Win32::System::Com::STREAM_SEEK_SET;
    unsafe {
        stream.Seek(0, STREAM_SEEK_SET, None).map_err(|e| format!("cannot rewind the capture stream: {e}"))?;
        let mut out: Vec<u8> = vec![];
        let mut buf = [0u8; 64 * 1024];
        loop {
            let mut read: u32 = 0;
            stream
                .Read(buf.as_mut_ptr() as *mut _, buf.len() as u32, Some(&mut read as *mut u32))
                .ok()
                .map_err(|e| format!("cannot read the capture stream: {e}"))?;
            if read == 0 {
                break;
            }
            out.extend_from_slice(&buf[..read as usize]);
        }
        Ok(out)
    }
}

/// Snapshot the webview on Linux, where the app runs on WebKitGTK.
///
/// `webkit_web_view_get_snapshot` is the sibling the Windows arm's comment names: a RENDER of the
/// webview's own content, not an OS window grab — so the sandboxed preview iframe is included, and an
/// occluded or unfocused window still produces real pixels rather than black.
///
/// # Threading — the same contract as the Windows arm, for a different reason
///
/// `with_webview` runs the closure on the GTK main thread, which is what `snapshot()` requires: it
/// asserts the calling thread owns the `MainContext` and panics otherwise. The completion callback then
/// fires later, on that same main loop — so the closure must only START the snapshot and hand the bytes
/// back through a channel. Waiting inside it would block the very loop that has to deliver the callback.
/// The wait therefore happens on the CALLER's thread, which is an appchan watcher thread, never the main
/// one.
#[cfg(target_os = "linux")]
fn capture_webview_png(app: &tauri::AppHandle, label: &str) -> Result<Vec<u8>, String> {
    use webkit2gtk::gio::Cancellable;
    use webkit2gtk::{SnapshotOptions, SnapshotRegion, WebViewExt};

    let window = resolve_window(app, label)?;

    // The snapshot completes on the WEBVIEW thread; we wait here. See the threading note above.
    let (tx, rx) = std::sync::mpsc::channel::<Result<Vec<u8>, String>>();

    window
        .with_webview(move |webview| {
            // `Visible` and not `FullDocument`: this must match what the Windows `CapturePreview`
            // produces, and what the frontend's registered crop rects are expressed in — the VIEWPORT.
            // `FullDocument` would render the whole scrollable page, silently making every named-target
            // crop land on the wrong pixels.
            //
            // `NONE` and not `TRANSPARENT_BACKGROUND`, for the same reason: the composited output the
            // user is actually looking at is opaque.
            webview.inner().snapshot(
                SnapshotRegion::Visible,
                SnapshotOptions::NONE,
                None::<&Cancellable>,
                move |res| {
                    let out = res
                        .map_err(|e| format!("webkit_web_view_get_snapshot failed: {e}"))
                        .and_then(|surface| {
                            let mut png: Vec<u8> = Vec::new();
                            surface
                                .write_to_png(&mut png)
                                .map_err(|e| format!("cannot encode the snapshot as PNG: {e}"))?;
                            Ok(png)
                        });
                    let _ = tx.send(out);
                },
            );
        })
        .map_err(|e| format!("cannot reach the webview: {e}"))?;

    let bytes = match rx.recv_timeout(CAPTURE_TIMEOUT) {
        Ok(r) => r?,
        Err(_) => {
            return Err(format!(
                "the webview did not complete a capture within {}ms",
                CAPTURE_TIMEOUT.as_millis()
            ))
        }
    };
    if bytes.is_empty() {
        // Distinct from a GError: an empty buffer means the encoder wrote nothing. It must not reach the
        // caller as a "successful" zero-byte PNG — `is_png` would reject it, but this names the cause.
        return Err("the webview returned an empty capture".into());
    }
    Ok(bytes)
}

/// The no-capture error, as a pure function so it is testable on every platform — including the ones
/// where the arm below does not compile.
///
/// It NAMES the platform. The previous text was the constant `"bsc shot is Windows-only for now"`, which
/// stayed literally true only while Windows was the only capturing platform and would have gone quietly
/// wrong the moment a second one landed — as it now has.
///
/// Gated to exactly its users — the no-capture arm, plus every platform's test run — rather than carrying
/// an `allow(dead_code)`, which would also mask a genuinely unused function later.
#[cfg(any(test, not(any(windows, target_os = "linux"))))]
fn unsupported_platform_error(os: &str) -> String {
    format!("bsc shot has no capture for this platform yet ({os}) — no capture was taken")
}

#[cfg(not(any(windows, target_os = "linux")))]
fn capture_webview_png(_app: &tauri::AppHandle, _label: &str) -> Result<Vec<u8>, String> {
    // Stated, not silent. A black PNG that reads as success is worse than no capture: the loop would
    // reason confidently about nothing. macOS's `WKWebView.takeSnapshot` is the equivalent when needed.
    Err(unsupported_platform_error(std::env::consts::OS))
}

// Clamping lives in `crop::crop_png` (where the image's real dimensions are known) and is tested there.
// Nothing here duplicates it: a second clamp would be a second source of truth for the same rule.

#[cfg(test)]
mod window_source_tests {
    //! A SOURCE-ASSERTING guard, because nothing at run time can observe the absence of a hard-coded
    //! window. The bug this replaces was silent in the worst way: the app ACCEPTED `--window` (the
    //! field deserialized fine), ignored it, captured `main`, and reported success — so a session
    //! could record a pixel verdict about a window it never photographed. Verified live on the
    //! pre-fix binary, which answered a `--window bsc-widget-spectrum` request with a 1920x1048
    //! capture of the main surface.

    /// This module's own source, up to the first test module and with comments stripped.
    ///
    /// BOTH TRIMS ARE LOAD-BEARING and both were found by the scanner reporting itself. Without the
    /// test cut, this file's own assertion strings contain `fn capture_webview_png` and inflate the
    /// arm count to five; without the comment strip, the doc paragraph explaining why the hard-coded
    /// lookup was removed is itself flagged as a hard-coded lookup. A scanner that cannot tell its
    /// subject from its own text is not evidence about the subject.
    ///
    /// RESOLVED through [`crate::testutil::module_source`], not read from a hard-coded path.
    ///
    /// This one is the reason a grep for `include_str!` is not the measurement. It read
    /// `CARGO_MANIFEST_DIR/src/shot/mod.rs` off disk, so `migrate-crate`'s refusal — which is lexical
    /// over `include_str!` — could not see it at all: clearing the four `include_str!` self-reads
    /// would have let `--apply` proceed and left these three guards panicking on a file that no longer
    /// existed. It was found by running the lib suite under `strace -e trace=openat,write
    /// --test-threads=1` and correlating each `openat` under this crate's own `src/` with the harness
    /// `write` announcing the running test.
    ///
    /// The resolver keeps the property this comment already claimed — a module that is in NEITHER home
    /// is a panic naming both, never a silent empty scan.
    fn source() -> String {
        let text = crate::testutil::module_source("shot/mod.rs");
        let code = match text.find("#[cfg(test)]") {
            Some(i) => &text[..i],
            None => panic!("no test module found — the trim is silently scanning the whole file"),
        };
        code.lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\n")
    }

    #[test]
    fn no_capture_path_resolves_a_hard_coded_window() {
        let src = source();
        // A scanner that silently stops matching reports zero offenders, which reads as a pass — so
        // assert the population it is scanning is the one expected first.
        assert!(
            src.contains("fn capture_webview_png"),
            "the scanner is looking at the wrong file — no capture function found"
        );
        let offenders: Vec<(usize, &str)> = src
            .lines()
            .enumerate()
            .filter(|(_, l)| l.contains("get_webview_window(\"main\")"))
            .map(|(i, l)| (i + 1, l.trim()))
            .collect();
        assert!(
            offenders.is_empty(),
            "a window is hard-coded, so `--window` would be accepted and ignored:\n{}",
            offenders
                .iter()
                .map(|(n, l)| format!("  line {n}: {l}"))
                .collect::<Vec<_>>()
                .join("\n")
        );
    }

    #[test]
    fn the_default_window_is_named_once_and_never_written_as_a_literal() {
        // THE BUG SHAPE, and the reason the two tests below are not enough: the
        // hard-coded lookup can be removed while `capture` still pins the label
        // to "main" one line up — the request's `window` deserializes fine, is
        // ignored, and a widget capture reports success about the main surface.
        // A bite proved the earlier guards passed against exactly that edit.
        //
        // So: no `"main"` literal anywhere in this module's real code. The
        // default has ONE home, `bsc_shot::DEFAULT_WINDOW`, and a call site that
        // wants it says so by name.
        let src = source();
        let offenders: Vec<(usize, &str)> = src
            .lines()
            .enumerate()
            .filter(|(_, l)| l.contains('"') && l.contains("main"))
            .filter(|(_, l)| l.split('"').skip(1).step_by(2).any(|lit| lit == "main"))
            .map(|(i, l)| (i + 1, l.trim()))
            .collect();
        assert!(
            offenders.is_empty(),
            "the default window is written as a literal instead of DEFAULT_WINDOW:\n{}",
            offenders.iter().map(|(n, l)| format!("  line {n}: {l}")).collect::<Vec<_>>().join("\n")
        );
        // And the request's field is what decides, rather than being read and dropped.
        assert!(
            src.contains("req.window.as_deref().unwrap_or(bsc_shot::DEFAULT_WINDOW)"),
            "`capture` no longer resolves the window from the REQUEST"
        );
    }

    #[test]
    fn every_capture_arm_takes_the_label_so_none_can_quietly_keep_its_own_default() {
        let src = source();
        let arms = src.matches("fn capture_webview_png").count();
        // Three: windows, linux, and the no-capture arm. If one is added or removed this count is
        // what says so, rather than the new arm silently going unchecked.
        assert_eq!(arms, 3, "the number of capture arms changed — recheck each takes a label");
        assert_eq!(
            src.matches("fn capture_webview_png(app: &tauri::AppHandle, label: &str)").count()
                + src.matches("fn capture_webview_png(_app: &tauri::AppHandle, _label: &str)").count(),
            arms,
            "a capture arm does not take a window label"
        );
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// THE REGRESSION GUARD for the ten PNGs that reached the repo (merge 6b52a96d). The app used to do
    /// `req.out.as_ref().map(PathBuf::from)`, handing a relative path to `fs::write`, which anchors at
    /// this process's cwd — `src-tauri/` under `tauri dev`.
    ///
    /// The property is ABSOLUTENESS, not a specific string: given an absolute shots dir, no request may
    /// produce a relative destination, because a relative one is the only kind that can land somewhere
    /// nobody chose. Reinstate `PathBuf::from` and the two relative cases here go red.
    #[test]
    fn no_request_can_steer_a_capture_outside_the_shots_dir() {
        let shots = std::path::Path::new(if cfg!(windows) { "C:\\ws\\shots" } else { "/ws/shots" });
        let req = |out: Option<&str>| ShotRequest { out: out.map(str::to_string), ..Default::default() };

        // The two shapes that actually leaked: a bare relative file, and a relative SUBPATH.
        assert_eq!(destination(&req(Some("flat.png")), shots, "abc"), shots.join("flat.png"));
        assert_eq!(destination(&req(Some("shots/kv-retest.png")), shots, "abc"), shots.join("shots/kv-retest.png"));

        // No `out` at all ⇒ the dir's own default.
        assert_eq!(destination(&req(None), shots, "abc"), shots.join("abc.png"));

        for out in [None, Some("flat.png"), Some("shots/kv-retest.png")] {
            let got = destination(&req(out), shots, "abc");
            assert!(got.is_absolute(), "{out:?} produced a relative destination: {}", got.display());
            assert!(got.starts_with(shots), "{out:?} escaped the shots dir: {}", got.display());
        }

        // An ABSOLUTE --out stays honored — the designer's known-good workaround must keep working.
        let abs = if cfg!(windows) { "C:\\elsewhere\\x.png" } else { "/elsewhere/x.png" };
        assert_eq!(destination(&req(Some(abs)), shots, "abc"), PathBuf::from(abs));
    }

    /// The no-capture error names the platform instead of asserting a stale one.
    #[test]
    fn the_no_capture_error_names_the_platform_rather_than_hardcoding_windows() {
        let msg = unsupported_platform_error("macos");
        assert!(msg.contains("macos"), "names the platform it actually ran on: {msg}");
        assert!(msg.contains("no capture was taken"), "and says nothing was captured: {msg}");
        assert!(!msg.contains("Windows-only"), "the old text was true only while Windows was the only arm");
    }

    #[test]
    fn a_named_target_registers_resolves_and_clears() {
        // The command + resolver are thin wrappers over this map — prove the register→resolve→clear
        // contract (and that an unregistered target is a STATED error) without a Tauri app.
        let targets = ShotTargets::default();
        let rect = Rect { x: 10, y: 20, w: 300, h: 200 };

        // Unregistered ⇒ a clear error, not a whole-screen fallback.
        assert!(resolve_from(&targets.0.lock().unwrap(), "preview").is_err());

        // Register (what set_shot_target_rect(Some) does) ⇒ resolves to the rect.
        targets.0.lock().unwrap().insert("preview".into(), rect);
        assert_eq!(resolve_from(&targets.0.lock().unwrap(), "preview").unwrap(), rect);

        // Clear (set_shot_target_rect(None)) ⇒ back to the error.
        targets.0.lock().unwrap().remove("preview");
        assert!(resolve_from(&targets.0.lock().unwrap(), "preview").is_err());
    }

    // ── `frame:<component>` targeting (#3469) ─────────────────────────────────────────────────────

    #[test]
    fn a_frame_target_is_routed_away_from_the_registered_rect_map() {
        // The prefix is the whole routing rule: `frame:X` must NEVER be looked up in the named-rect
        // map (it would miss and report "navigate first" for a component that IS mounted), and a plain
        // target must never be mistaken for a frame request.
        assert_eq!("frame:Heatmap".strip_prefix(FRAME_PREFIX), Some("Heatmap"));
        assert_eq!("preview".strip_prefix(FRAME_PREFIX), None);
        // A component whose NAME contains the prefix word is still addressed by its own id.
        assert_eq!("frame:frame".strip_prefix(FRAME_PREFIX), Some("frame"));
    }

    #[test]
    fn a_css_rect_becomes_an_integer_crop_without_losing_a_partial_pixel() {
        // getBoundingClientRect() is fractional; the crop grid is integral. Floor the origin and ceil
        // the size — the same rounding the frontend applies registering `preview` — so a box that
        // partially covers a pixel keeps it.
        let r = rect_from_css([10.4, 20.6, 300.2, 199.1], "Heatmap").unwrap();
        assert_eq!(r, Rect { x: 10, y: 20, w: 301, h: 200 });
        // Exact integers pass through untouched.
        assert_eq!(rect_from_css([0.0, 0.0, 8.0, 6.0], "X").unwrap(), Rect { x: 0, y: 0, w: 8, h: 6 });
    }

    #[test]
    fn a_negative_origin_clamps_instead_of_wrapping_through_u32() {
        // A frame scrolled above/left of the viewport reports negatives. `-4.0 as u32` is 0 on this
        // path only because we clamp FIRST — without it the cast saturates/wraps and the crop lands
        // somewhere absurd, which the downstream clamp would then quietly absorb.
        let r = rect_from_css([-4.0, -12.5, 50.0, 40.0], "Offscreen").unwrap();
        assert_eq!(r, Rect { x: 0, y: 0, w: 50, h: 40 });
    }

    #[test]
    fn a_zero_size_frame_is_a_stated_error_not_a_zero_pixel_crop() {
        // Mounted but not laid out yet. Saying so beats handing back an empty PNG that reads as a
        // successful capture of nothing.
        for bad in [[0.0, 0.0, 0.0, 10.0], [0.0, 0.0, 10.0, 0.0], [0.0, 0.0, -5.0, 10.0]] {
            let err = rect_from_css(bad, "Unlaid").unwrap_err();
            assert!(err.contains("zero-size"), "{err}");
            assert!(err.contains("Unlaid"), "names the component: {err}");
        }
        // NaN must error too — every comparison against NaN is false, so a bare `<=` check would
        // have waved it through and produced a garbage crop.
        assert!(rect_from_css([0.0, 0.0, f64::NAN, 10.0], "Unlaid").is_err());
        assert!(rect_from_css([0.0, 0.0, 10.0, f64::INFINITY], "Unlaid").is_err());
    }
